import test from 'node:test';
import assert from 'node:assert/strict';
import { LIMITS, ResourceError, inspectIndex, getRecord, frameRange, decodeRD } from '../index.mjs';

// All fixtures are original, generated bytes. No official resource payload is stored here.
function rd({ version = 0, width = 3, height = 2, paletteLength = 768 } = {}) {
  const headerLength = version === 2 ? 20 : 16;
  const data = new Uint8Array(headerLength + width * height + (version === 2 ? paletteLength : 0));
  const header = new DataView(data.buffer);
  data.set([0x52, 0x44, version, 0xa5]);
  header.setUint32(4, width, true);
  header.setUint32(8, height, true);
  header.setUint32(12, 0xfedcba98, true); // Deliberately not the payload length.
  if (version === 2) header.setUint32(16, paletteLength, true);
  for (let i = 0; i < width * height; i += 1) data[headerLength + i] = i % 256;
  for (let i = 0; i < (version === 2 ? paletteLength : 0); i += 1) data[headerLength + width * height + i] = (i * 7) % 256;
  return data;
}

function index(records = [{}]) {
  const result = new Uint8Array(records.length * 40);
  const view = new DataView(result.buffer);
  records.forEach((record, ordinal) => {
    const start = ordinal * 40;
    view.setUint32(start, record.id ?? 87, true);
    view.setUint32(start + 4, record.byteOffset ?? 0, true);
    view.setUint32(start + 8, record.byteLength ?? 22, true);
    view.setUint32(start + 12, 0xffffffff, true);
    view.setUint32(start + 16, 0xfffffff0, true);
    view.setUint32(start + 20, record.width ?? 3, true);
    view.setUint32(start + 24, record.height ?? 2, true);
    result.fill(0x7c, start + 28, start + 40);
  });
  return result;
}

function expectCode(callback, code) {
  assert.throws(callback, (error) => error instanceof ResourceError && error.code === code);
}

test('v0 returns exact raw indices and preserves opaque header word', () => {
  const result = decodeRD(rd());
  assert.equal(result.version, 0);
  assert.equal(result.width, 3);
  assert.equal(result.height, 2);
  assert.deepEqual(result.pixels, new Uint8Array([0, 1, 2, 3, 4, 5]));
  assert.equal(result.opaque.headerByte3, 0xa5);
  assert.equal(result.opaque.headerWord12, 0xfedcba98);
  assert.equal(result.opaque.paletteBytes.length, 0);
});

test('v2 accepts all observed palette lengths as opaque bytes', () => {
  for (const paletteLength of [516, 711, 759, 768]) {
    const result = decodeRD(rd({ version: 2, paletteLength }));
    assert.equal(result.opaque.paletteBytes.length, paletteLength);
    assert.equal(result.opaque.paletteBytes[1], 7);
    assert.deepEqual(result.pixels, new Uint8Array([0, 1, 2, 3, 4, 5]));
  }
});

test('ArrayBuffer and nonzero-offset Uint8Array inputs are supported', () => {
  const original = rd({ version: 2 });
  const wrapper = new Uint8Array(original.length + 17);
  wrapper.set(original, 11);
  assert.deepEqual(decodeRD(wrapper.subarray(11, 11 + original.length)), decodeRD(original.buffer));
  const originalIndex = index([{}, { id: 87, byteOffset: 22 }]);
  const wrappedIndex = new Uint8Array(originalIndex.length + 15);
  wrappedIndex.set(originalIndex, 9);
  const sliced = wrappedIndex.subarray(9, 9 + originalIndex.length);
  assert.deepEqual(getRecord(sliced, 1), getRecord(originalIndex.buffer, 1));
  assert.deepEqual(inspectIndex(sliced), inspectIndex(originalIndex));
});

test('returned pixels and opaque bytes are owned copies', () => {
  const input = rd({ version: 2 });
  const result = decodeRD(input);
  input.fill(99);
  assert.equal(result.pixels[0], 0);
  assert.equal(result.opaque.paletteBytes[1], 7);
  const sourceIndex = index();
  const record = getRecord(sourceIndex, 0);
  sourceIndex.fill(0);
  assert.equal(record.opaque.indexBytes12to19[0], 255);
  assert.equal(record.opaque.indexBytes28to39[0], 0x7c);
});

test('Uint8Array subclasses cannot turn returned copies into shared views', () => {
  class ViewReturningBytes extends Uint8Array {
    slice(start, end) { return this.subarray(start, end); }
  }
  const input = new ViewReturningBytes(rd({ version: 2 }));
  const result = decodeRD(input);
  assert.equal(result.pixels.constructor, Uint8Array);
  input.fill(99);
  assert.equal(result.pixels[0], 0);
  assert.equal(result.opaque.paletteBytes[1], 7);
});

test('ordinal selection retains repeated IDs instead of deduplicating', () => {
  const input = index([{ id: 5 }, { id: 5, byteOffset: 22 }]);
  assert.equal(getRecord(input, 0).id, getRecord(input, 1).id);
  assert.equal(getRecord(input, 1).byteOffset, 22);
  assert.equal(inspectIndex(input).recordCount, 2);
});

test('frameRange produces exclusive byte range and validates paired size', () => {
  const record = getRecord(index([{ byteOffset: 100 }]), 0, { pairedByteCount: 122 });
  assert.deepEqual(frameRange(record, { pairedByteCount: 122 }), { start: 100, end: 122, byteLength: 22 });
  expectCode(() => frameRange(record, { pairedByteCount: 121 }), 'PAIRED_BOUNDS');
  expectCode(() => getRecord(index(), 0, { pairedByteCount: 21 }), 'PAIRED_BOUNDS');
});

test('index range addition does not wrap at UInt32', () => {
  const input = index([{ byteOffset: 0xfffffff0, byteLength: 64 }]);
  assert.equal(inspectIndex(input).maximumEndOffset, 0x100000030);
  expectCode(() => inspectIndex(input, { pairedByteCount: 0xffffffff }), 'PAIRED_BOUNDS');
});

test('overlap gaps zero lengths and maximum nested end remain observations', () => {
  const summary = inspectIndex(index([
    { byteOffset: 0, byteLength: 100 },
    { byteOffset: 5, byteLength: 10 },
    { byteOffset: 20, byteLength: 0 },
  ]));
  assert.equal(summary.maximumEndOffset, 100);
  assert.equal(summary.overlappingAdjacentRanges, 1);
  assert.equal(summary.noncontiguousAdjacentPairs, 2);
  assert.equal(summary.zeroLengthRecords, 1);
  expectCode(() => frameRange(getRecord(index([{ byteLength: 0 }]), 0)), 'FRAME_TRUNCATED');
});

test('record dimensions and byte length must agree with RD payload', () => {
  const input = rd();
  const valid = getRecord(index(), 0);
  assert.equal(decodeRD(input, { record: valid }).pixels.length, 6);
  expectCode(() => decodeRD(input, { record: { ...valid, width: 4 } }), 'DIMENSION_MISMATCH');
  expectCode(() => decodeRD(input, { record: { ...valid, byteLength: 23 } }), 'RECORD_LENGTH_MISMATCH');
});

test('invalid input types and ordinals fail explicitly', () => {
  for (const value of [null, undefined, [], 'RD', new DataView(new ArrayBuffer(40))]) {
    expectCode(() => decodeRD(value), 'INVALID_INPUT');
  }
  for (const ordinal of [-1, 1, 0.5, NaN, Infinity, Number.MAX_SAFE_INTEGER]) {
    expectCode(() => getRecord(index(), ordinal), 'ORDINAL_BOUNDS');
  }
});

test('empty truncated and over-budget indices are rejected', () => {
  for (const length of [0, 1, 39, 41, 79]) expectCode(() => inspectIndex(new Uint8Array(length)), 'INDEX_LENGTH');
  expectCode(() => getRecord(new Uint8Array(LIMITS.indexBytes + 40), 0), 'INDEX_BUDGET');
});

test('frame headers validate magic and truncate safely', () => {
  for (const length of [0, 1, 2, 3, 4, 15]) expectCode(() => decodeRD(rd().slice(0, length)), 'FRAME_TRUNCATED');
  const badMagic = rd(); badMagic[0] = 0;
  expectCode(() => decodeRD(badMagic), 'RD_MAGIC');
  expectCode(() => decodeRD(rd({ version: 2 }).slice(0, 19)), 'FRAME_TRUNCATED');
});

test('compressed and unknown RD versions are never silently decoded', () => {
  for (const version of [1, 3, 4, 255]) {
    const input = rd(); input[2] = version;
    expectCode(() => decodeRD(input), 'UNSUPPORTED_VERSION');
  }
});

test('zero enormous and multiplication-unsafe dimensions are rejected before allocation', () => {
  for (const [width, height, code] of [
    [0, 1, 'ZERO_DIMENSION'], [1, 0, 'ZERO_DIMENSION'],
    [0xffffffff, 0xffffffff, 'PIXEL_BUDGET'], [4096, 4096, 'PIXEL_BUDGET'],
    [LIMITS.pixels + 1, 1, 'PIXEL_BUDGET'],
  ]) {
    const input = rd(); const header = new DataView(input.buffer);
    header.setUint32(4, width, true); header.setUint32(8, height, true);
    expectCode(() => decodeRD(input), code);
  }
});

test('v0 and v2 reject truncation and trailing bytes', () => {
  for (const version of [0, 2]) {
    const input = rd({ version });
    expectCode(() => decodeRD(input.slice(0, input.length - 1)), 'FRAME_LENGTH');
    const trailing = new Uint8Array(input.length + 1); trailing.set(input);
    expectCode(() => decodeRD(trailing), 'FRAME_LENGTH');
  }
});

test('v2 invalid palette layouts are rejected without inferring colors', () => {
  for (const length of [0, 1, 767, 769, 0xffffffff]) {
    const input = rd({ version: 2 }); new DataView(input.buffer).setUint32(16, length, true);
    expectCode(() => decodeRD(input), 'PALETTE_LAYOUT');
  }
});

test('frame and caller-supplied record budgets fail before reads', () => {
  const valid = getRecord(index(), 0);
  expectCode(() => decodeRD(new Uint8Array(LIMITS.frameBytes + 1)), 'FRAME_BUDGET');
  expectCode(() => frameRange({ ...valid, byteLength: LIMITS.frameBytes + 1 }), 'FRAME_BUDGET');
  expectCode(() => frameRange({ ...valid, width: 0xffffffff }), 'PIXEL_BUDGET');
  for (const byteOffset of [-1, Infinity, 1.5, 0x100000000]) {
    expectCode(() => frameRange({ ...valid, byteOffset }), 'INVALID_RECORD');
  }
  for (const pairedByteCount of [-1, 1.5, Infinity, Number.MAX_SAFE_INTEGER + 1]) {
    expectCode(() => frameRange(valid, { pairedByteCount }), 'INVALID_PAIRED_SIZE');
  }
});
